// Voice selection is language constrained. Never silently read Arabic with a non-Arabic voice.
const listeningDialog=document.createElement('dialog');listeningDialog.id='storyListening';listeningDialog.className='story-listening';document.body.append(listeningDialog);
let listeningState=null,voiceRun=0;
function availableStoryVoices(language){if(!('speechSynthesis' in window))return[];const prefix=language==='ar'?'ar':'en';return speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().split(/[-_]/)[0]===prefix).sort((a,b)=>{const score=v=>(v.lang.toLowerCase()===(prefix==='ar'?'ar-om':'en-us')?8:0)+(v.lang.toLowerCase()==='ar-sa'?4:0)+(v.localService?2:0)+(v.default?1:0);return score(b)-score(a)})}
const speechLexicon={'عيسى':'عِيسَى','مدرك':'مُدْرِك','صمود':'صُمُود','عُمان':'عُمَان','الفلج':'الفَلَج','الكُمّة':'الكُمَّة','المصرّ':'المُصَرّ','الميكانيكي':'المِيكَانِيكِي','الطيّار':'الطَّيَّار','المسعف':'المُسْعِف'};
function pronunciationText(text,state){if(state.story.language!=='ar')return text;let out=String(text).replace(/\.{3}/g,'…').replace(/[↗✦✧]/g,'');const map={...speechLexicon};if(state.nameSound?.trim())map[state.story.name]=state.nameSound.trim();for(const [word,sound] of Object.entries(map)){const safe=word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');out=out.replace(new RegExp('(?<![\\p{L}\\p{M}])'+safe+'(?![\\p{L}\\p{M}])','gu'),()=>sound)}return out}
function speechSentences(text){const sentences=String(text).replace(/\.{3}/g,'…').match(/[^.!?؟؛…]+[.!?؟؛…]*/gu)||[];return sentences.flatMap(s=>{const chunks=[];let part='';for(const word of s.trim().split(/\s+/)){if(part.length+word.length>190){chunks.push(part);part=''}part+=(part?' ':'')+word}if(part)chunks.push(part);return chunks}).filter(Boolean)}
function stopStoryVoice(update=true){voiceRun++;if('speechSynthesis' in window)speechSynthesis.cancel();if(listeningState){listeningState.speaking=false;listeningState.paused=false;if(update)syncListeningControls()}}
function syncListeningControls(){const s=listeningState;if(!s||!$('#listenStart'))return;$('#listenStart').textContent=s.speaking?t('■ أوقف القراءة','■ Stop reading'):t('▶ استمع للحكاية','▶ Listen to the story');$('#listenPause').disabled=!s.speaking;$('#listenPause').textContent=s.paused?t('متابعة ▶','Resume ▶'):t('إيقاف مؤقت Ⅱ','Pause Ⅱ')}
function populateStoryVoices(){const s=listeningState;if(!s||!listeningDialog.open)return;const select=$('#storyVoice'),old=select.value;s.voices=availableStoryVoices(s.story.language);select.innerHTML=s.voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join('');if(s.voices.some(v=>v.voiceURI===old))select.value=old;select.disabled=!s.voices.length;$('#listenStart').disabled=!s.voices.length;$('#voiceAvailability').textContent=s.voices.length?t('نختار صوتًا يطابق لغة القصة. جرّب الأصوات المتاحة لاختيار الأنسب لطفلك.','Only voices matching the story language are listed. Try the available voices to find your favorite.'):s.story.language==='ar'?t('لا يتوفّر صوت عربي على هذا الجهاز حاليًا. يمكنك تصفّح القصة؛ لن نقرأها بصوت أجنبي.','No Arabic voice is currently available on this device. The story remains readable; we will not use a foreign-language voice.'):t('لا يتوفّر صوت إنجليزي على هذا الجهاز حاليًا.','No English voice is currently available on this device.');}
async function renderListeningPage(){const s=listeningState;if(!s)return;const token=++s.renderToken;$('#listenPage').textContent=`${s.index+1} / ${s.story.pages.length}`;$('#listenTranscript').textContent=s.story.pages[s.index];$('#listenSentence').textContent='';try{const canvas=await paintBookPage(s.story,s.index,{size:1400,portrait:false});if(listeningState!==s||token!==s.renderToken){canvas.width=1;return}const old=$('#listenArt canvas');if(old){old.width=1;old.height=1}$('#listenArt').replaceChildren(canvas)}catch(e){$('#listenError').textContent=e.message}}
async function openStoryListening(story){
 stopStoryVoice(false);const s=listeningState={story:structuredClone(story),index:0,renderToken:0,speaking:false,paused:false,voices:[],nameSound:''};
 listeningDialog.dir=story.language==='ar'?'rtl':'ltr';listeningDialog.innerHTML=`<div class="dialog-head"><div><span class="overline">${t('نقرأ بهدوء… ونتخيّل معًا','LISTEN SLOWLY. IMAGINE TOGETHER.')}</span><h2>${esc(story.title)}</h2></div><button class="close" id="listenClose" aria-label="${t('إغلاق القراءة','Close story player')}">×</button></div><div class="listening-layout"><div><div class="listen-art" id="listenArt"></div><div class="scene-nav"><button id="listenPrev" aria-label="${t('الصفحة السابقة','Previous page')}">←</button><span id="listenPage"></span><button id="listenNext" aria-label="${t('الصفحة التالية','Next page')}">→</button></div></div><div class="listen-settings"><span class="voice-badge">${t('قراءة جملة بجملة','ONE SENTENCE AT A TIME')}</span><label class="field">${t('الصوت','Voice')}<select id="storyVoice"></select></label><label class="field">${t('إيقاع الحكاية','Story pace')}<select id="storyVoiceRate"><option value="0.7">${t('هادئ جدًا','Very gentle')}</option><option value="0.86" selected>${t('هادئ وواضح','Gentle & clear')}</option><option value="1">${t('طبيعي','Natural')}</option></select></label>${story.language==='ar'?`<label class="field">${t('نطق اسم البطل — اختياري','Hero name pronunciation — optional')}<input id="heroNameSound" maxlength="60" placeholder="${esc(speechLexicon[story.name]||story.name)}"><small>${t('يمكن إضافة التشكيل لتوضيح نطق الاسم.','Add vowel marks to clarify the name.')}</small></label>`:''}<label class="book-option"><input id="listenAllPages" type="checkbox" checked>${t('متابعة صفحات القصة تلقائيًا','Continue through all story pages')}</label><p id="voiceAvailability" class="voice-availability" role="status"></p><div class="voice-buttons"><button class="button" id="listenStart">${t('▶ استمع للحكاية','▶ Listen to the story')}</button><button class="button outline" id="listenPause" disabled>${t('إيقاف مؤقت Ⅱ','Pause Ⅱ')}</button></div><p class="voice-caption" id="listenSentence" aria-live="polite"></p><details class="voice-transcript"><summary>${t('نص الصفحة','Page transcript')}</summary><p id="listenTranscript"></p></details><button class="button outline" id="listenBook">${t('شاهد الكتيّب المتحرك ↗','Watch the book preview ↗')}</button><p class="voice-footnote">${t('القراءة بصوت الجهاز، وتختلف جودتها حسب الصوت المتاح. فيديو الكتيّب القابل للتنزيل صامت؛ الاستماع يعمل داخل الموقع.','Playback uses a device voice; quality depends on the available voice. Downloaded book videos are silent; listening works on the site.')}</p><p id="listenError" role="alert"></p></div></div>`;
 $('#listenClose').onclick=()=>listeningDialog.close();$('#listenPrev').onclick=()=>moveListeningPage(-1);$('#listenNext').onclick=()=>moveListeningPage(1);$('#listenStart').onclick=()=>s.speaking?stopStoryVoice():startStoryVoice();$('#listenPause').onclick=()=>{if(!s.speaking)return;if(s.paused)speechSynthesis.resume();else speechSynthesis.pause();s.paused=!s.paused;syncListeningControls()};
 ['storyVoice','storyVoiceRate'].forEach(id=>$('#'+id).onchange=()=>stopStoryVoice());if($('#heroNameSound'))$('#heroNameSound').oninput=e=>{s.nameSound=e.target.value;stopStoryVoice()};$('#listenBook').onclick=()=>{stopStoryVoice();openBookCinema(s.story)};
 listeningDialog.showModal();populateStoryVoices();await renderListeningPage();
}
async function moveListeningPage(delta){const s=listeningState;if(!s)return;stopStoryVoice();s.index=Math.max(0,Math.min(s.story.pages.length-1,s.index+delta));await renderListeningPage()}
function startStoryVoice(){const s=listeningState;if(!s)return;const voice=s.voices.find(v=>v.voiceURI===$('#storyVoice').value);if(!voice||voice.lang.toLowerCase().split(/[-_]/)[0]!==s.story.language){populateStoryVoices();return}stopStoryVoice(false);const run=++voiceRun,rate=Number($('#storyVoiceRate').value);s.speaking=true;s.paused=false;$('#listenError').textContent='';syncListeningControls();
 const readPage=()=>{if(run!==voiceRun||listeningState!==s)return;const sentences=speechSentences(s.story.pages[s.index]);let sentence=0;
  const next=()=>{if(run!==voiceRun||listeningState!==s)return;if(sentence>=sentences.length){if($('#listenAllPages').checked&&s.index<s.story.pages.length-1){s.index++;renderListeningPage().then(()=>{if(run===voiceRun)setTimeout(readPage,400)})}else{stopStoryVoice();$('#listenSentence').textContent=t('انتهت القراءة. ما أكثر شيء أعجبك؟','The reading is finished. What did you like most?')}return}
   const text=sentences[sentence++],utterance=new SpeechSynthesisUtterance(pronunciationText(text,s));utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=rate;utterance.pitch=1;utterance.onstart=()=>{if(run===voiceRun)$('#listenSentence').textContent=text};utterance.onend=()=>{if(run===voiceRun)setTimeout(next,240)};utterance.onerror=e=>{if(run!==voiceRun)return;stopStoryVoice();$('#listenError').textContent=t('تعذّرت القراءة بهذا الصوت. اختر صوتًا آخر ثم أعد المحاولة.','This voice could not read the story. Choose another voice and retry.')};s.utterance=utterance;speechSynthesis.speak(utterance);
  };next();
 };readPage();
}
listeningDialog.addEventListener('close',()=>{stopStoryVoice(false);const old=$('#listenArt canvas');if(old){old.width=1;old.height=1}listeningState=null});
if('speechSynthesis' in window)speechSynthesis.addEventListener('voiceschanged',populateStoryVoices);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&listeningState?.speaking)stopStoryVoice()});
// Every existing story video/listen entry now uses the same language-aware reader.
showFilm=openStoryListening;
